<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$message='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if($pdo){$q=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach(['site_tagline','contact_email'] as $key)$q->execute([$key,trim($_POST[$key]??'')]);$message='Settings saved.';}}$values=['site_tagline'=>'Relaxing Sounds for Sleep, Focus and Calm','contact_email'=>''];if($pdo){$s=$pdo->query("SELECT setting_key,setting_value FROM settings WHERE setting_key IN ('site_tagline','contact_email')");foreach($s as $r)$values[$r['setting_key']]=$r['setting_value'];}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Settings</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><h1>Site Settings</h1><?php if($message):?><p role="status"><?=e($message)?></p><?php endif;?><form method="post" class="card"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><p><label>Site tagline<input name="site_tagline" value="<?=e($values['site_tagline'])?>"></label></p><p><label>Contact email<input type="email" name="contact_email" value="<?=e($values['contact_email'])?>"></label></p><button>Save settings</button></form></main></body></html>
